import os, re, collections, functools, sys
root='AlgebraicJacobian'
def mod_of(path):
    return path[:-5].replace('/','.')
files={}
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'):
            p=os.path.join(dp,f); files[mod_of(p)]=p
files['AlgebraicJacobian']='AlgebraicJacobian.lean'
imports={}
for m,p in files.items():
    ims=[]
    for line in open(p):
        mt=re.match(r'^import\s+([A-Za-z0-9_.]+)',line)
        if mt: ims.append(mt.group(1))
        elif line.strip() and not line.startswith('--') and not line.startswith('/-') and not line.startswith('set_option') and 'import' not in line:
            pass
    imports[m]=ims
internal={m:[i for i in imports[m] if i in files] for m in files}
external={m:[i for i in imports[m] if i not in files] for m in files}
# reverse deps
rev=collections.defaultdict(list)
for m,ims in internal.items():
    for i in ims: rev[i].append(m)
# transitive internal closure
@functools.lru_cache(maxsize=None)
def closure(m):
    s=set()
    for i in internal[m]:
        s.add(i); s|=closure(i)
    return frozenset(s)
sys.setrecursionlimit(10000)
# longest chain (depth)
@functools.lru_cache(maxsize=None)
def depth(m):
    if not internal[m]: return 0
    return 1+max(depth(i) for i in internal[m])
print("modules:",len(files))
print("== deepest chain (project-internal import depth) ==")
for m in sorted(files,key=lambda m:-depth(m))[:8]:
    print(f"  depth {depth(m):>3}  {m}")
# reconstruct one longest path
m=max(files,key=depth); path=[m]
while internal[m]:
    m=max(internal[m],key=depth); path.append(m)
print("\n== a longest path (%d modules) ==" % len(path))
for x in reversed(path): print("   ", x)
print("\n== widest transitive closures ==")
for m in sorted(files,key=lambda m:-len(closure(m)))[:10]:
    print(f"  {len(closure(m)):>4} internal deps  {m}")
print("\n== most-depended-on modules ==")
tot=collections.Counter()
for m in files:
    for d in closure(m): tot[d]+=1
for d,c in tot.most_common(12): print(f"  {c:>4} dependents  {d}")
print("\n== external (mathlib) import counts ==")
ext=collections.Counter()
for m in files:
    for e in external[m]: ext[e]+=1
print("  distinct mathlib imports:",len(ext))
for e,c in ext.most_common(15): print(f"  {c:>4}x {e}")
print("\n== modules importing Mathlib umbrella-ish heavy files ==")
for m,es in sorted(external.items()):
    heavy=[e for e in es if e.count('.')<=1 or e in ('Mathlib',)]
    if heavy: print("  ",m,heavy)
